<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { BookOpen, Flower2, Footprints, House, Volume2, VolumeX, Moon, X, Check, Play, ArrowLeft, ArrowUpRight, Send, Sparkles, ChevronRight, Maximize2, Minimize2, MessageCircle } from 'lucide-vue-next'
import { disclose as vDisclose } from '../../shared/ui/interaction/disclose'
import SnapSlider from '../../shared/ui/interaction/SnapSlider.vue'
import CompanionScene from './CompanionScene.vue'
import { stableProjection } from './companion.presentation'
import { useCompanionWorld, focusRemaining, clockText } from './companion.store'
import { useTodayLogic } from '../today/today.logic'
import { useAuthStore } from '../auth/auth.store'
import type { Memory, Project, WorldEvent } from './companion.types'

const town = useCompanionWorld()
const { world, loaded, loading, busy, error, feedback, activeIntents } = town
const { tasks, plannedTasks, error: taskError, feedback: taskFeedback, canComplete, act, last, reverse } = useTodayLogic()
const auth = useAuthStore()
const quiet = ref(false)
const overview = ref(false)
const bubblePreferenceKey = `better-self:town-text-bubbles:${auth.user?.publicId || 'guest'}`
const textBubbles = ref(false)
try { textBubbles.value = localStorage.getItem(bubblePreferenceKey) === 'on' } catch { /* Browsing remains available without storage. */ }
function toggleTextBubbles() { textBubbles.value = !textBubbles.value; if (textBubbles.value) quiet.value = false; try { localStorage.setItem(bubblePreferenceKey, textBubbles.value ? 'on' : 'off') } catch { /* Keep the preference for this visit. */ } }
const soundEnabled = ref(false)
const selectedResident = ref<string | null>(null)
const selectedConversation = ref<string | null>(null)
const journalOpen = ref(false)
const storiesOpen = ref(false)
const focusOpen = ref(false)
const focusDismissed = ref(false)
const selectedPlace = ref('')
const selectedProject = ref<string | null>(null)
const thought = ref('')
const thoughtPriority = ref<'explicit' | 'passing'>('passing')
const taskId = ref('')
const duration = ref(25)
const durationOptions = [15, 25, 45, 60]
const now = ref(Date.now())
const name = ref(auth.user?.displayName || '新邻居')
const timezone = computed(() => world.value?.timezone || auth.user?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone)
const minutes = computed(() => {
  const parts = new Intl.DateTimeFormat('en-GB', { timeZone: timezone.value, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(now.value))
  return Number(parts.find(p => p.type === 'hour')?.value || 0) * 60 + Number(parts.find(p => p.type === 'minute')?.value || 0)
})
const time = computed(() => new Intl.DateTimeFormat('zh-CN', { timeZone: timezone.value, hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(now.value))
const cafeStatusLabel = computed(() => world.value?.cafeStatus === 'closing' ? '咖啡馆收店中' : world.value?.cafeStatus === 'closed' ? '咖啡馆已打烊' : '咖啡馆营业中')
const sceneActors = stableProjection(() => world.value ? [world.value.avatar, ...world.value.residents].map(actor => {
  const state = world.value?.residentStates?.find(state => state.id === actor.id)
  const plan = state?.plan
  return { id: actor.id, name: actor.name, role: actor.id === world.value?.avatar.id ? 'user' : residentRole(actor.id), location: actor.place, action: actor.label, activity: actor.activity, objectKind: world.value?.projects?.find(project => project.id === plan?.targetId)?.objectKind, destination: plan?.action === 'travel' ? plan.place : undefined, positionId: state?.positionId }
}) : [])
const sceneProjects = stableProjection(() => (world.value?.projects || []).map(item => ({ id: item.id, title: item.title, place: item.place, status: item.status, progress: item.progress, objectKind: item.objectKind })))
const sceneConversations = stableProjection(() => (world.value?.conversations || []).filter(item => item.status === 'active').map(item => ({ id: item.id, place: item.place, status: item.status, topicId: item.topicId, participantIds: item.participantIds, turns: item.turns.slice(-2) })))
const sceneObjects = stableProjection(() => (world.value?.objects || []).map(item => ({ id: item.id, kind: item.kind, place: item.place, label: item.label, state: item.state, projectId: item.projectId })))
const resident = computed(() => world.value?.residents.find(actor => actor.id === selectedResident.value))
const memories = computed(() => world.value?.memories.filter(memory => memory.ownerId === selectedResident.value).slice().reverse() || [])
const opinions = computed(() => {
  const seen = new Set<string>()
  return memories.value.filter(memory => {
    if (memory.sourceType !== 'reflection') return false
    const text = memory.text.trim().replace(/\s+/g, '')
    if (seen.has(text)) return false
    seen.add(text); return true
  }).slice(0, 2)
})
const experiences = computed(() => memories.value.filter(memory => memory.sourceType !== 'reflection'))
function evidence(memory: Memory) { return world.value?.memories.filter(item => memory.evidenceIds?.includes(item.id)) || [] }
const person = computed(() => world.value?.residentStates?.find(state => state.id === selectedResident.value))
const projects = computed(() => world.value?.projects || [])
const project = computed(() => projects.value.find(item => item.id === selectedProject.value))
// `careerIntent` is the durable direction. A public project or a short interruption can replace
// lifeIntent several times in one day, so it must never be used as the resident's profession.
const careerDirection = computed(() => person.value?.careerIntent?.purpose || person.value?.occupation || '还在慢慢找方向')
const personalGoal = computed(() => person.value?.lifeIntent?.purpose || projects.value.find(item => item.id === person.value?.goal)?.title || person.value?.thought || '眼前的小事')
const normalizedPurpose = (value: string) => value.replace(/\s+/g, '')
const showCurrentThread = computed(() => personalGoal.value !== '眼前的小事' && normalizedPurpose(personalGoal.value) !== normalizedPurpose(careerDirection.value))
const pausedAction = computed(() => person.value?.suspendedAction?.plan || null)
const events = computed(() => (world.value?.events || []).slice().reverse())
const storyEvents = computed(() => events.value.filter(event => !selectedProject.value || event.projectId === selectedProject.value))
const latestConversation = computed(() => (world.value?.conversations || []).filter(talk => talk.status === 'active' && talk.turns.length).slice().reverse()[0])
const conversation = computed(() => world.value?.conversations?.find(item => item.id === selectedConversation.value))
const conversationTitle = computed(() => projects.value.find(item => item.id === conversation.value?.topicId)?.title || `${placeLabel(conversation.value?.place) || '小街'}的一段闲聊`)
const residentConversations = computed(() => (world.value?.conversations || []).filter(talk => talk.participantIds.includes(selectedResident.value || '')).slice().reverse().slice(0, 2))
const relationships = computed(() => Object.entries(person.value?.relationships || {}).filter(([id]) => id !== selectedResident.value && world.value?.residents.some(actor => actor.id === id)).sort((a, b) => b[1] - a[1]))
const diary = computed(() => world.value?.diary.slice().reverse() || [])
const focusTask = computed(() => tasks.value.find(task => task.taskPublicId === world.value?.focus?.taskId))
const selectedTask = computed(() => tasks.value.find(task => task.publicId === taskId.value))
const remaining = computed(() => world.value?.focus ? focusRemaining(world.value.focus.endsAt, now.value, world.value.focus.startedAt) : 0)
const focusIntent = computed(() => activeIntents.value.find(item => item.kind === 'focus'))
const lastFocusTaskId = computed(() => world.value?.intents.slice().reverse().find(intent => intent.kind === 'focus' && intent.taskId && ['active', 'done'].includes(intent.status))?.taskId)
const completableTask = computed(() => focusTask.value || tasks.value.find(task => task.taskPublicId === lastFocusTaskId.value))
const focusVisible = computed(() => focusOpen.value || (!focusDismissed.value && (Boolean(world.value?.focus) || Boolean(completableTask.value && canComplete(completableTask.value)))))
function toggleFocusPanel() { const next = !focusVisible.value; focusOpen.value = next; focusDismissed.value = !next; if (next) { selectedResident.value = null; selectedConversation.value = null; journalOpen.value = false; storiesOpen.value = false } }
function closeFocusPanel() { focusOpen.value = false; focusDismissed.value = true }
// TownPlaces hands out one home per resident ("home-owner", "home-student", "home-self", ...)
// instead of a single shared "home", so this stays a prefix match rather than five literal keys -
// a new resident's home just works without touching this dictionary.
const places: Record<string, string> = { cafe: '咖啡馆', street: '门前小街', garden: '小花园' }
function placeLabel(place?: string | null): string {
  if (!place) return ''
  if (place === 'home-self') return '自己家'
  if (place === 'home' || place.startsWith('home-')) return '住处'
  return places[place] || place
}
function residentRole(id: string) {
  const actor = world.value?.residents.find(item => item.id === id)
  const state = world.value?.residentStates?.find(item => item.id === id)
  // The actor record is the public, backend-authoritative responsibility. Occupation is only a
  // self-description fallback for newly hand-authored residents whose role has not been filled.
  return actor?.role || state?.occupation || '小街邻居'
}
function selectResident(id: string) { selectedConversation.value = null; closeFocusPanel(); if (id === world.value?.avatar.id) { selectedResident.value = id; overview.value = false; selectedPlace.value = ''; selectedProject.value = null; journalOpen.value = false; storiesOpen.value = false; return } if (world.value?.residents.some(actor => actor.id === id)) { selectedResident.value = id; overview.value = false; selectedPlace.value = ''; selectedProject.value = null; journalOpen.value = false; storiesOpen.value = false; quiet.value = false } }
function source(memory: Memory) {
  const who = world.value?.residents.find(actor => actor.id === memory.sourceId)?.name || (memory.sourceId === world.value?.avatar.id ? '你的小人' : memory.sourceId)
  return memory.sourceType === 'reflection' ? '从经历里慢慢形成的看法' : memory.sourceType === 'seed' ? '搬来前的生活 · 初始记忆' : memory.sourceType === 'heard' ? `听${who || '邻居'}说起 · 转述` : '亲身经历 · 观察'
}
function actorName(id: string) { return world.value?.residents.find(actor => actor.id === id)?.name || (id === world.value?.avatar.id ? world.value.avatar.name : '邻居') }
function relationshipLabel(value: number) { return value >= 70 ? '很聊得来' : value >= 40 ? '渐渐熟悉' : value >= 12 ? '还在认识' : value > 0 ? '有点疏远' : '有点不同意见' }
function followProject(item: Project) { selectedConversation.value = null; closeFocusPanel(); overview.value = false; selectedProject.value = item.id; selectedPlace.value = item.place; selectedResident.value = null; storiesOpen.value = true; journalOpen.value = false; quiet.value = false }
function followEvent(event: WorldEvent) { selectedConversation.value = null; closeFocusPanel(); selectedPlace.value = event.place; if (event.actorIds[0]) selectedResident.value = event.actorIds[0]; storiesOpen.value = false }
function openStories() { selectedConversation.value = null; closeFocusPanel(); storiesOpen.value = !storiesOpen.value; selectedProject.value = null; selectedResident.value = null; journalOpen.value = false; quiet.value = false }
function openJournal() { selectedConversation.value = null; closeFocusPanel(); journalOpen.value = !journalOpen.value; storiesOpen.value = false; selectedResident.value = null; quiet.value = false }
function openConversation(id: string) { const talk = world.value?.conversations?.find(item => item.id === id); if (!talk) return; closeFocusPanel(); selectedConversation.value = id; selectedResident.value = null; selectedPlace.value = talk.place; journalOpen.value = false; storiesOpen.value = false; quiet.value = false }
async function sendThought() { if (!thought.value.trim() || busy.value) return; if (await town.intend('thought', { text: thought.value.trim(), priority: thoughtPriority.value })) thought.value = '' }
async function visitProject() { if (!project.value) return; await town.intend('thought', { text: `我想去${placeLabel(project.value.place) || project.value.place}看看${project.value.title}`, priority: 'explicit' }) }
function dateTime(at: string) { return new Intl.DateTimeFormat('zh-CN', { timeZone: timezone.value, month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).format(new Date(at)) }
async function startFocus() {
  if (!selectedTask.value?.taskPublicId || !canComplete(selectedTask.value)) return
  await town.intend('focus', { taskId: selectedTask.value.taskPublicId, durationMinutes: duration.value })
}
async function completeTask() {
  if (!completableTask.value || !canComplete(completableTask.value)) return
  await act(completableTask.value, 'COMPLETED')
}
function toggleQuiet() { quiet.value = !quiet.value; if (quiet.value) { selectedConversation.value = null; closeFocusPanel(); soundEnabled.value = false; selectedResident.value = null; journalOpen.value = false; storiesOpen.value = false; selectedPlace.value = ''; selectedProject.value = null } }
function refresh() { if (!document.hidden) void town.load(true) }
let ticker: ReturnType<typeof setInterval> | undefined
let poller: ReturnType<typeof setInterval> | undefined
onMounted(() => {
  void town.load().then(() => { if (world.value) void town.load(true) })
  ticker = setInterval(() => { now.value = Date.now() }, 1000)
  poller = setInterval(refresh, 5000)
  document.addEventListener('visibilitychange', refresh)
})
onBeforeUnmount(() => { town.dispose(); clearInterval(ticker); clearInterval(poller); document.removeEventListener('visibilitychange', refresh) })
</script>

<template>
  <main class="companion-page" :class="{ quiet }" aria-labelledby="companion-title">
    <header class="street-heading">
      <RouterLink class="back-link" to="/today" aria-label="回到今日"><ArrowLeft :size="17"/><span>今日</span></RouterLink>
      <div class="street-brand"><span class="brand-symbol">✳</span><div><h1 id="companion-title">梧桐小街</h1></div></div>
      <div class="street-tools"><span class="local-time">{{ time }} <span>· {{ world?.weather === 'rain' ? '细雨' : '晴' }} · {{ cafeStatusLabel }}</span></span><button class="tool-button" :aria-label="soundEnabled ? '关闭环境声' : '打开环境声'" :aria-pressed="soundEnabled" :disabled="!world" @click="soundEnabled = !soundEnabled; if (soundEnabled) quiet = false"><Volume2 v-if="soundEnabled" :size="17"/><VolumeX v-else :size="17"/><span>环境声{{ soundEnabled ? '开' : '关' }}</span></button><button class="tool-button" :aria-label="textBubbles ? '关闭文字气泡' : '打开文字气泡'" :title="textBubbles ? '关闭文字气泡' : '打开文字气泡'" :aria-pressed="textBubbles" @click="toggleTextBubbles"><MessageCircle :size="17"/><span>文字气泡</span></button><button class="tool-button" :aria-label="quiet ? '退出安静模式' : '安静模式'" :aria-pressed="quiet" @click="toggleQuiet"><Moon :size="17"/><span>{{ quiet ? '退出安静' : '安静模式' }}</span></button></div>
    </header>
    <p v-if="error" class="notice error" role="alert">{{ error }} <button class="text-button" :disabled="loading || busy" @click="town.load()">重新连接</button></p>
    <div v-if="!loaded" class="arrival-loading" role="status">{{ loading ? '街角的灯，正在亮起来…' : '小街暂时无法打开，请重新连接。' }}</div>
    <section v-else-if="!world" class="arrival">
      <div class="arrival-art" aria-hidden="true"><span>☕</span><span>⌂</span><span>✿</span><i></i></div>
      <p class="kicker">你的新住处，就在咖啡馆旁边</p><h2>生活已经开始，<br>只差你搬进来。</h2><p>阿禾在准备咖啡，小川带着备考书。<br>知夏答应画一张海报，青叔的花也快开了。</p>
      <form @submit.prevent="town.join(name, timezone)"><label for="neighbor-name">大家怎么称呼你</label><input id="neighbor-name" v-model="name" maxlength="24" autocomplete="nickname" placeholder="新邻居"/><button class="main-button" :disabled="busy || !name.trim()">{{ busy ? '正在安顿…' : '搬进这条小街' }} <House :size="17"/></button></form><small>不必照料谁。忙几天再回来，也可以从当下开始。</small>
    </section>
    <template v-else>
      <section class="town-stage" aria-label="正在生活的小街">
        <CompanionScene :residents="sceneActors" :weather="world.weather === 'rain' ? 'rain' : 'clear'" :minutes="minutes" :sound-enabled="soundEnabled" :cafe-open="world.cafeStatus !== 'closed' && world.cafeStatus !== 'closing'" :text-bubbles="textBubbles && !quiet" :overview="overview" :selected-resident-id="selectedResident || undefined" :selected-place="selectedPlace || undefined" :projects="sceneProjects" :conversations="sceneConversations" :objects="sceneObjects" :suppress-hover="Boolean(resident || conversation || storiesOpen || journalOpen || focusVisible)" @select-resident="selectResident" @select-conversation="openConversation" @select-project="id => { const item = projects.find(item => item.id === id); if (item) followProject(item) }"/>
        <button v-if="!quiet" class="scene-note" :disabled="!latestConversation" @click="latestConversation && openConversation(latestConversation.id)"><span class="living-dot"></span><span>{{ latestConversation ? `${placeLabel(latestConversation.place)}里，有人聊了起来` : '点一个小人，看看 TA 的一天' }}</span><ChevronRight v-if="latestConversation" :size="12"/></button>
        <nav v-if="!quiet" class="scene-navigation" aria-label="小街故事"><button class="view-toggle" :aria-pressed="overview" :aria-label="overview ? '回到街角' : '看整条街'" :title="overview ? '回到街角' : '看整条街'" @click="overview = !overview"><Minimize2 v-if="overview" :size="16"/><Maximize2 v-else :size="16"/></button><button :class="{ selected: storiesOpen }" @click="openStories"><Sparkles :size="16"/>小街正在发生<span v-if="projects.some(item => item.status === 'active')" class="living-dot"/></button><button :class="{ selected: journalOpen }" @click="openJournal"><BookOpen :size="16"/>我的日记</button></nav>

        <aside v-if="resident && !quiet" :key="resident.id" class="story-panel person-panel" aria-label="居民的记忆">
          <header class="panel-header"><div class="person-identity"><span class="portrait" :class="`portrait-${resident.id}`">{{ resident.name.slice(-1) }}</span><div><span class="kicker">{{ residentRole(resident.id) }} · {{ placeLabel(resident.place) }}</span><h2>{{ resident.name }}</h2></div></div><button class="close-button" aria-label="收起居民记忆" @click="selectedResident = null"><X :size="18"/></button></header>
          <div class="panel-scroll"><p class="current-action"><span class="living-dot"></span>{{ resident.label }}</p>
            <template v-if="person"><blockquote class="inner-thought">“{{ person.thought || personalGoal }}”</blockquote><div class="personal-plan"><span class="kicker">长期想走的方向</span><p>{{ careerDirection }}</p><template v-if="showCurrentThread"><span class="kicker current-thread">眼前在惦记</span><p class="life-thread">{{ personalGoal }}</p></template><span v-if="person.plan" class="plan-reason">{{ person.plan.reason }}</span><p v-if="pausedAction" class="paused-action">暂放着：{{ pausedAction.reason || '一件还没做完的事' }}</p></div><section v-if="opinions.length" class="opinions"><span class="kicker">现在的看法</span><article v-for="opinion in opinions" :key="opinion.id"><p>{{ opinion.text }}</p><details v-if="evidence(opinion).length" v-disclose><summary>为什么会这样想</summary><div v-for="item in evidence(opinion)" :key="item.id" class="evidence"><p>{{ item.text }}</p><small>{{ source(item) }} · {{ dateTime(item.at) }}</small></div></details></article></section><div v-if="relationships.length" class="relationship-list"><span class="kicker">在这条街上的牵挂</span><button v-for="[id, value] in relationships" :key="id" @click="selectResident(id)"><span class="mini-portrait" :class="`portrait-${id}`">{{ actorName(id).slice(-1) }}</span><strong>{{ actorName(id) }}</strong><span>{{ relationshipLabel(value) }}</span><ChevronRight :size="13"/></button></div></template>
            <section v-for="conversation in residentConversations" :key="conversation.id" class="conversation"><span class="kicker">{{ conversation.status === 'active' ? '此刻的对话' : '刚才聊起' }} · {{ placeLabel(conversation.place) }}</span><div v-for="(turn, index) in conversation.turns.slice(-4)" :key="index" class="conversation-turn" :class="{ self: turn.speakerId === resident.id }"><button @click="selectResident(turn.speakerId)">{{ actorName(turn.speakerId) }}</button><p>{{ turn.text }}</p></div></section>
            <details class="memory-detail" :open="!person" v-disclose><summary>那些留下痕迹的事 <span>{{ experiences.length }}</span></summary><ol class="memory-list"><li v-for="memory in experiences" :key="memory.id"><p>{{ memory.text }}</p><small>{{ source(memory) }} · {{ dateTime(memory.at) }}</small></li></ol><p v-if="!experiences.length">日子会慢慢留下痕迹。</p></details>
          </div>
        </aside>

        <aside v-if="storiesOpen && !quiet" :key="selectedProject || 'street-stories'" class="story-panel" aria-label="小街故事">
          <header class="panel-header"><div><p class="kicker">有人惦记，有人动手，有人刚刚听说</p><h2>{{ project?.title || '这条街，正在发生' }}</h2></div><button class="close-button" aria-label="收起故事" @click="storiesOpen = false; selectedProject = null; selectedPlace = ''"><X :size="18"/></button></header>
          <div class="panel-scroll"><template v-if="project"><div class="project-feature"><span class="project-symbol">{{ project.objectKind === 'flowers' ? '✿' : project.objectKind === 'poster' ? '▧' : project.objectKind === 'books' ? '▤' : '☕' }}</span><p>{{ project.description }}</p><span class="project-status">{{ project.status === 'ready' || project.status === 'celebrating' ? '已经准备好了' : project.status === 'idea' ? '一个刚冒头的念头' : '一点一点，在变成真的' }}</span><div class="project-progress" :aria-label="`${project.title}完成${project.progress}%`"><span :style="{ width: `${project.progress}%` }"/></div><div class="contributors"><button v-for="id in project.contributors" :key="id" @click="selectResident(id)">{{ actorName(id) }}留下了一点心意</button></div><button class="main-button" :disabled="busy" @click="visitProject"><Footprints :size="15"/>我也想过去看看</button></div></template>
            <div v-else class="project-list"><button v-for="item in projects" :key="item.id" class="project-story" @click="followProject(item)"><span class="project-symbol">{{ item.objectKind === 'flowers' ? '✿' : item.objectKind === 'poster' ? '▧' : item.objectKind === 'books' ? '▤' : '☕' }}</span><span><strong>{{ item.title }}</strong><small>{{ item.description }}</small><span class="project-stage">{{ placeLabel(item.place) }} · {{ item.status === 'ready' || item.status === 'celebrating' ? '准备好了' : item.status === 'idea' ? '还在酝酿' : '正在发生' }}</span></span><ArrowUpRight :size="15"/></button></div>
            <div class="story-timeline"><span class="kicker">{{ project ? '这件事，是怎样走到这里的' : '生活里的小小后续' }}</span><button v-for="event in storyEvents.slice(0, 14)" :key="event.id" @click="followEvent(event)"><time>{{ dateTime(event.at) }}</time><p>{{ event.text }}</p><small>去{{ placeLabel(event.place) || '街上' }}看看 <ArrowUpRight :size="12"/></small></button><p v-if="!storyEvents.length" class="empty-story">先坐一会儿。有人正在把心里的念头，变成一件小事。</p></div>
          </div>
        </aside>

        <aside v-if="conversation && !quiet" :key="conversation.id" class="story-panel conversation-panel" aria-label="完整对话"><header class="panel-header"><div><p class="kicker">{{ conversation.status === 'active' ? '正在聊' : '刚才的一段话' }} · {{ placeLabel(conversation.place) }}</p><h2>{{ conversationTitle }}</h2></div><button class="close-button" aria-label="收起对话" @click="selectedConversation = null; selectedPlace = ''"><X :size="18"/></button></header><div class="panel-scroll"><div class="conversation-participants"><button v-for="id in conversation.participantIds" :key="id" @click="selectResident(id)">{{ actorName(id) }} <ArrowUpRight :size="12"/></button></div><div v-for="(turn, index) in conversation.turns" :key="`${turn.speakerId}:${turn.at}:${index}`" class="conversation-turn"><button @click="selectResident(turn.speakerId)">{{ actorName(turn.speakerId) }}</button><p>{{ turn.text }}</p></div></div></aside>
        <aside v-if="journalOpen && !quiet" class="story-panel journal-panel" aria-label="小人的日记"><header class="panel-header"><div><p class="kicker">不用补读所有对话</p><h2>在这里度过的日子</h2></div><button class="close-button" aria-label="收起日记" @click="journalOpen = false"><X :size="18"/></button></header><div class="panel-scroll"><p v-if="world.offlineSummary" class="return-note">{{ world.offlineSummary }}</p><ol class="memory-list"><li v-for="entry in diary" :key="entry.id"><small>{{ dateTime(entry.at) }}</small><p>{{ entry.text }}</p></li></ol><p v-if="!diary.length">今天的故事，才刚刚开始。</p></div></aside>
      <section v-if="focusVisible" class="focus-card" aria-label="一起专注"><div class="card-heading"><span class="kicker">你做自己的事，小人就在旁边</span><button class="close-button" aria-label="收起专注" @click="closeFocusPanel"><X :size="16"/></button></div><template v-if="world.focus"><h2>{{ focusTask?.taskTitle || '正在陪你专注' }}</h2><p>{{ focusTask?.status === 'DONE' ? '这项 Todo 已记录完成。可以继续安静坐一会儿，或结束这段专注。' : remaining ? '小人已经找好座位。你做自己的事就好。' : '这段专注时间到了。做完与否，由你决定。' }}</p><div class="button-row"><button v-if="focusIntent" class="soft-button" :disabled="busy" @click="town.cancel(focusIntent.id)">结束这段专注</button><button v-if="focusTask && canComplete(focusTask)" class="main-button" :disabled="busy" @click="completeTask"><Check :size="16"/>我已完成这项 Todo</button></div></template><template v-else><form class="focus-form" @submit.prevent="startFocus"><label class="task-label">今天想专注什么<select v-model="taskId" aria-label="选择一项 Todo" :disabled="busy"><option value="" disabled>选择一项 Todo</option><option v-for="task in plannedTasks" :key="task.publicId" :value="task.publicId">{{ task.taskTitle }}</option></select></label><label class="duration-label">时长 · {{ duration }} 分钟<SnapSlider :model-value="durationOptions.indexOf(duration)" aria-label="专注时长" :disabled="busy" :min="0" :max="durationOptions.length - 1" :step="1" :value-text="`${duration} 分钟`" @update:model-value="i => duration = durationOptions[i]" /></label><button class="main-button" :disabled="busy || !selectedTask?.taskPublicId || !canComplete(selectedTask)"><Play :size="15"/>一起专注</button></form><p v-if="!plannedTasks.length">暂时没有待办，先让小人陪你坐一会儿。<RouterLink to="/today">去安排今天</RouterLink></p><div v-if="completableTask && canComplete(completableTask)" class="finished-focus"><span>刚才：{{ completableTask.taskTitle }}</span><button class="soft-button" @click="completeTask">我已完成这项 Todo</button></div></template><small>计时结束、小人读书，都不会替你勾选真实 Todo。</small><p v-if="taskError" class="notice error" role="alert">{{ taskError }}</p><p v-if="taskFeedback" class="task-feedback" role="status">{{ taskFeedback.text }} <button v-if="last" class="text-button" @click="reverse">撤销记录</button></p></section>
        <div class="scene-caption"><button class="self-mark" aria-label="看看我的小人" title="看看我的小人" @click="selectResident(world.avatar.id)">{{ world.avatar.name.slice(-1) }}</button><div><strong>{{ world.avatar.name }}</strong><span>{{ world.avatar.label }}</span></div><span class="caption-location">{{ placeLabel(world.avatar.place) }}</span><button class="text-button focus-toggle" :aria-expanded="focusVisible" @click="toggleFocusPanel"><span v-if="world.focus" class="timer" role="timer">{{ clockText(remaining) }}</span><Play v-else :size="14"/>{{ world.focus ? '正在陪你专注' : '留一段专注时间' }}</button></div>
      </section>

      <section v-if="!quiet" class="thought-dock" aria-label="捎一个想法"><form @submit.prevent="sendThought"><Flower2 :size="20" class="thought-icon"/><label class="sr-only" for="inner-thought">捎一个内心念头</label><input id="inner-thought" v-model="thought" maxlength="200" placeholder="脑海里突然冒出一个念头……比如，想去看看知夏的海报" :disabled="busy"/><select v-model="thoughtPriority" aria-label="念头优先级" :disabled="busy"><option value="passing">有空的时候</option><option value="explicit">现在就想</option></select><button class="send-thought" :disabled="busy || !thought.trim()" aria-label="捎给小人"><Send :size="17"/></button></form><div class="thought-shortcuts"><span>或者轻轻捎一句</span><button :disabled="busy" @click="town.intend('rest')">休息一会儿</button><button :disabled="busy" @click="town.intend('walk')">出去散散步</button><button :disabled="busy" @click="town.intend('home')">先回家吧</button><button :disabled="busy" @click="town.intend('flowers')">有空想看看花</button></div></section>
      <div v-if="!quiet" class="intent-area"><p v-if="feedback && !activeIntents.some(intent => intent.feedback === feedback)" class="feedback" role="status">{{ feedback }}</p><div v-for="intent in activeIntents.filter(item => item.kind !== 'focus')" :key="intent.id" class="intent-item"><span>{{ intent.feedback || (intent.status === 'pending' ? '念头先放在心里，等一会儿。' : '正在做这件事。') }}</span><button class="text-button" :disabled="busy" @click="town.cancel(intent.id)">收回想法</button></div></div>



    </template>
  </main>
</template>

